/* Study 18: synthetic six-type composer. No Reddit, entered-URL fetches, device files/camera, uploads or persistent drafts. */
(function(){
'use strict';
const C=id=>document.getElementById(id),T=window.RelaxeStudyTheme;
const config={appearance:'light',palette:'blue',text:'1',width:'390'};
const types={text:'Text',link:'Link',image:'Image',gallery:'Gallery',video:'Video',poll:'Poll'};
let fixture='ready',posting=false,closed=false,dialogOrigin=null,leaveAction=null,submitTimer=null,allowNavigation=false,lastSignedInAccount='weekendreader';
let activeType='text',suggesting=false,suggestionTimer=null,suggestionGeneration=0;
const bodies={text:'',link:'',image:'',gallery:'',video:'',poll:''};
let pollSequence=2,pollOptions=[{id:1,value:''},{id:2,value:''}],pollDuration='3';
let imageChoice=null;
let videoChoice=null;
let videoBlobUrl=null,videoBlobPromise=null,videoPageLeaving=false;
let galleryItems=[],gallerySequence=0;
const imageSamples=[
 {key:'forest',src:'assets/forest.jpg',name:'forest.jpg',description:'Green trees in a forest',kind:'Image'},
 {key:'mountain',src:'assets/mountain.jpg',name:'mountain.jpg',description:'Mountain landscape',kind:'Image'},
 {key:'earth',src:'assets/earth-poster.png',name:'earth.gif',description:'Earth against a dark background',kind:'GIF · first-frame preview'}
];
const dialog=C('compose-dialog'),content=C('compose-dialog-content');
const dirty=()=>Boolean(C('post-title').value||C('post-url').value||C('post-body').value||Object.values(bodies).some(Boolean)||imageChoice||videoChoice||galleryItems.length||pollOptions.some(option=>option.value)||pollDuration!=='3');
const required=()=>fixture==='flair-required';
const guest=()=>fixture==='guest'||C('post-account').value==='guest';
function message(id,text){C(id).textContent=text;C(id).hidden=!text}
function theme(){const settings={foundation:'selected',...config},direction=T.directions[0],phone=C('compose-phone');for(const [key,value]of Object.entries(T.tokens(direction,settings)))phone.style.setProperty(key,value);T.setStyleAttributes(phone,direction,settings);phone.style.setProperty('--w',config.width+'px');phone.style.setProperty('--h',({360:800,390:844,600:960,720:480}[config.width]||844)+'px');phone.dataset.largeText=String(+config.text>=2);window.RelaxeShell?.setContext({account:guest()?'guest':C('post-account').value,...config})}
function sync(){
 const type=C('post-type').value,supported=Object.hasOwn(bodies,type);
 if(type!==activeType){pauseComposerVideos();if(activeType in bodies)bodies[activeType]=C('post-body').value;cancelSuggestion();activeType=type;if(supported)C('post-body').value=bodies[type];message('url-error','');C('post-url').removeAttribute('aria-invalid')}
 C('link-form').hidden=type!=='link';C('image-form').hidden=type!=='image';C('text-form').hidden=!supported;C('type-placeholder').hidden=supported;C('type-title').textContent=types[type]+' post';C('type-copy').textContent='This form is the next review step. Its existing capabilities will be retained. All six post types keep their input in this page; submission is simulated.';
 C('flair-label').textContent=required()?'Post flair · required':'Post flair';C('post-flair').required=required();
 C('post-account').disabled=posting||fixture==='account-loading';for(const id of ['post-subreddit','post-type','post-title','post-body','post-url','post-flair','post-spoiler','post-nsfw','post-notifications'])C(id).disabled=posting;
 C('suggest-title').disabled=closed||posting||suggesting;C('suggest-title').textContent=suggesting?'Getting title…':'Suggest title';
 for(const button of document.querySelectorAll('.format-bar button'))button.disabled=posting;
 for(const button of document.querySelectorAll('#image-form button'))button.disabled=posting||closed;
 renderImage();
 C('gallery-form').hidden=type!=='gallery';renderGallery();
 C('video-form').hidden=type!=='video';renderVideo();
 C('poll-form').hidden=type!=='poll';renderPoll();
 C('post-rules').disabled=!C('post-subreddit').value;C('post-preview').disabled=closed||!supported||posting;
 C('compose-post').disabled=closed||posting||!supported||guest()||fixture==='account-loading'||required()&&!C('post-flair').value;
 C('compose-post').textContent=posting?'Posting…':'Post';C('compose-close').disabled=closed;
 C('compose-notice').hidden=false;C('compose-notice').textContent=posting?'Posting…':guest()?'Sign in to post. Your writing stays here.':fixture==='account-loading'?'Loading your account. Your writing stays here.':'';C('compose-notice').hidden=!C('compose-notice').textContent;
 message('flair-status',fixture==='flair-loading'?'Checking flair requirements…':fixture==='flair-error'?'Couldn’t check flair requirements. You can retry; posting is still available.':required()&&!C('post-flair').value?'Choose a post flair before posting.':'');C('retry-flair').hidden=fixture!=='flair-error';

 C('post-form').hidden=closed;C('composer-closed').hidden=!closed;theme();
}
function show(title,build){pauseComposerVideos();if(!dialog.open)dialogOrigin=document.activeElement;C('compose-dialog-title').textContent=title;content.replaceChildren();build(content);dialog.showModal();C('compose-dialog-close').focus()}
function paragraph(node,text){const p=document.createElement('p');p.textContent=text;node.append(p);return p}
function action(node,label,handler,primary=false){const button=document.createElement('button');button.type='button';button.textContent=label;if(primary)button.className='primary';button.addEventListener('click',handler);node.append(button);return button}
function clearPollError(){message('poll-error','');for(const input of C('poll-options').querySelectorAll('textarea'))input.removeAttribute('aria-invalid')}
function renderPoll(){
 const list=C('poll-options');list.replaceChildren();
 pollOptions.forEach((option,index)=>{
  const row=document.createElement('div');row.className='poll-option';const label=document.createElement('label');label.htmlFor='poll-option-'+option.id;label.textContent='Option '+(index+1);const input=document.createElement('textarea');input.id=label.htmlFor;input.rows=2;input.value=option.value;input.disabled=posting||closed;input.setAttribute('aria-describedby','poll-help poll-error');input.addEventListener('input',()=>{option.value=input.value;clearPollError();message('post-error','');message('post-result','')});row.append(label,input);
  if(pollOptions.length>2){const remove=action(row,'Remove',()=>{if(posting||closed)return;pollOptions=pollOptions.filter(item=>item.id!==option.id);clearPollError();message('post-result','');renderPoll();C('poll-option-'+pollOptions[Math.min(index,pollOptions.length-1)].id).focus()});remove.className='poll-remove';remove.setAttribute('aria-label','Remove option '+(index+1));remove.disabled=posting||closed}
  list.append(row);
 });
 C('poll-add').hidden=pollOptions.length>=6;C('poll-add').disabled=posting||closed;C('poll-duration').value=pollDuration;C('poll-duration').disabled=posting||closed;
}
function pollPreview(node){const section=document.createElement('section');section.className='poll-preview';section.setAttribute('aria-label','Poll preview');const heading=document.createElement('h5');heading.textContent='Poll';section.append(heading);const options=pollOptions.filter(option=>option.value!=='');if(options.length){const list=document.createElement('ol');for(const option of options){const item=document.createElement('li');item.textContent=option.value;list.append(item)}section.append(list)}else paragraph(section,'No options entered.');paragraph(section,'Voting length: '+pollDuration+(pollDuration==='1'?' day':' days'));node.append(section)}
function imageUnavailable(){return C('compose-attachment-result').value==='preview-error'}
function imageDescription(choice=imageChoice){return choice.name+' · '+choice.kind+(choice.source==='camera'?' · Camera':'')}
function renderImage(){
 C('image-empty').hidden=Boolean(imageChoice);C('image-selected').hidden=!imageChoice;
 const thumbnail=C('image-thumbnail');
 if(!imageChoice){thumbnail.removeAttribute('src');thumbnail.alt='';return}
 const unavailable=imageUnavailable();thumbnail.hidden=unavailable;C('image-unavailable').hidden=!unavailable;C('image-retry').hidden=!unavailable;
 if(thumbnail.getAttribute('src')!==imageChoice.src)thumbnail.src=imageChoice.src;thumbnail.alt=imageChoice.description;C('image-caption').textContent=imageDescription();
}
function imageFigure(node,choice=imageChoice){const figure=document.createElement('figure');figure.className='attachment-preview';if(!imageUnavailable()){const img=document.createElement('img');img.src=choice.src;img.alt=choice.description;figure.append(img)}const caption=document.createElement('figcaption');caption.textContent=imageDescription(choice)+(imageUnavailable()?' · Preview unavailable':'');figure.append(caption);node.append(figure)}
function acceptImage(sample,source){if(activeType==='gallery'){addGalleryImage(sample,source);return}imageChoice={...sample,source};message('image-error','');message('post-error','');message('post-result','');sync();dialogOrigin=C('image-replace');dialog.close()}
function chooseImage(){
 if(posting||closed)return;
 if(C('compose-attachment-result').value==='picker-error'){message(activeType==='gallery'?'gallery-error':'image-error','Couldn’t select an image. Try again.');if(dialog.open)dialog.close();return}
 show('Choose image',node=>{const choices=document.createElement('div');choices.className='attachment-choices';for(const sample of imageSamples){const button=action(choices,'',()=>acceptImage(sample,'library'));button.setAttribute('aria-label','Choose '+sample.name);const thumb=document.createElement('img');thumb.src=sample.src;thumb.alt='';const label=document.createElement('span');label.textContent=sample.name+' · '+sample.kind;button.append(thumb,label)}node.append(choices);action(node,'Cancel',()=>dialog.close())});
}
function takePhoto(){
 if(posting||closed)return;
 const result=C('compose-attachment-result').value;
 if(result==='camera-denied'||result==='camera-unavailable'){message(activeType==='gallery'?'gallery-error':'image-error',result==='camera-denied'?'Camera access is required to take a photo. You can choose an image instead.':'No camera is available. You can choose an image instead.');if(dialog.open)dialog.close();return}
 show('Camera preview',node=>{const img=document.createElement('img');img.src=imageSamples[1].src;img.alt='Sample mountain photograph';img.className='camera-fixture';node.append(img);const actions=document.createElement('div');actions.className='dialog-actions';action(actions,'Cancel',()=>dialog.close());action(actions,'Use photo',()=>acceptImage({...imageSamples[1],name:'camera-photo.jpg'},'camera'),true);node.append(actions)});
}
function replaceImage(){if(posting||closed)return;show('Replace image',node=>{const actions=document.createElement('div');actions.className='image-actions';action(actions,'Choose image',chooseImage);action(actions,'Take photo',takePhoto);node.append(actions);action(node,'Cancel',()=>dialog.close())})}
const galleryPending=()=>galleryItems.some(item=>item.pending);
function galleryButton(id){return C('gallery-edit-'+id)||C('gallery-count')}
function renderGallery(){
 const list=C('gallery-images');list.replaceChildren();C('gallery-count').textContent=galleryItems.length+' of 20 images';
 C('gallery-add').hidden=galleryItems.length>=20;C('gallery-add').disabled=posting||closed||galleryPending();C('gallery-complete').hidden=!galleryPending();
 for(const [index,item]of galleryItems.entries()){
  const card=document.createElement('article');card.className='gallery-card';card.setAttribute('role','listitem');card.dataset.imageId=item.id;
  const heading=document.createElement('h4');heading.textContent='Image '+(index+1);card.append(heading);
  if(!imageUnavailable()){const img=document.createElement('img');img.src=item.src;img.alt=item.description;card.append(img)}else paragraph(card,'Preview unavailable');
  const summary=paragraph(card,item.caption||item.name);summary.className='gallery-summary';if(item.outbound)paragraph(card,'Link added');paragraph(card,item.pending?'Uploading…':'Ready');
  const actions=document.createElement('div');actions.className='gallery-actions';
  const edit=action(actions,'Edit',()=>editGalleryItem(item.id));edit.id='gallery-edit-'+item.id;edit.setAttribute('aria-label','Edit image '+(index+1)+' details');edit.disabled=posting||closed||item.pending;
  const remove=action(actions,'',()=>removeGalleryItem(item.id));remove.innerHTML=T.icon('close');remove.setAttribute('aria-label','Remove image '+(index+1));remove.disabled=posting||closed||(item.pending&&!imageUnavailable());
  card.append(actions);list.append(card);
 }
}
function addGalleryImage(sample,source){
 if(posting||closed||galleryPending()||galleryItems.length>=20)return;
 const mode=C('compose-gallery-upload').value,item={...sample,source,id:'g'+(++gallerySequence),caption:'',outbound:'',pending:mode!=='ready'};galleryItems.push(item);
 message('gallery-error','');message('gallery-status',item.pending?'Uploading image…':'Image added.');message('post-error','');message('post-result','');sync();dialogOrigin=item.pending?C('gallery-count'):galleryButton(item.id);dialog.close();
 if(mode==='failure')setTimeout(()=>{const at=galleryItems.findIndex(entry=>entry.id===item.id);if(at<0||!galleryItems[at].pending)return;galleryItems.splice(at,1);message('gallery-status','Couldn’t upload '+item.name+'. The image was removed. Try adding it again.');sync()},650);
}
function addGallery(){if(posting||closed||galleryPending()||galleryItems.length>=20)return;show('Add image',node=>{const actions=document.createElement('div');actions.className='image-actions';action(actions,'Choose image',chooseImage);action(actions,'Take photo',takePhoto);node.append(actions);action(node,'Cancel',()=>dialog.close())})}
function removeGalleryItem(id){const at=galleryItems.findIndex(item=>item.id===id);if(at<0||posting||closed||(galleryItems[at].pending&&!imageUnavailable()))return;galleryItems.splice(at,1);message('gallery-error','');message('gallery-status','Image removed.');message('post-result','');sync();(galleryItems[at]?galleryButton(galleryItems[at].id):!C('gallery-add').disabled?C('gallery-add'):C('gallery-count')).focus()}
function editGalleryItem(id){
 const item=galleryItems.find(entry=>entry.id===id);if(!item||item.pending||posting||closed)return;
 show('Image '+(galleryItems.indexOf(item)+1)+' details',node=>{node.className='gallery-editor';imageFigure(node,item);
  const captionLabel=document.createElement('label');captionLabel.textContent='Caption (optional)';captionLabel.htmlFor='gallery-caption';node.append(captionLabel);
  const caption=document.createElement('textarea');caption.id='gallery-caption';caption.rows=3;caption.maxLength=180;caption.value=item.caption;caption.setAttribute('aria-describedby','gallery-caption-count');node.append(caption);
  const count=paragraph(node,caption.value.length+' / 180');count.id='gallery-caption-count';caption.addEventListener('input',()=>{caption.value=caption.value.slice(0,180);if(/[\uD800-\uDBFF]$/.test(caption.value))caption.value=caption.value.slice(0,-1);count.textContent=caption.value.length+' / 180'});
  const urlLabel=document.createElement('label');urlLabel.textContent='Outbound URL (optional)';urlLabel.htmlFor='gallery-outbound';node.append(urlLabel);
  const url=document.createElement('input');url.id='gallery-outbound';url.type='text';url.inputMode='url';url.spellcheck=false;url.value=item.outbound;node.append(url);
  const actions=document.createElement('div');actions.className='dialog-actions';action(actions,'Cancel',()=>dialog.close());action(actions,'Save details',()=>{const current=galleryItems.find(entry=>entry.id===id);if(!current)return;current.caption=caption.value.slice(0,180);current.outbound=url.value;message('post-result','');sync();dialogOrigin=galleryButton(id);dialog.close()},true);node.append(actions);
 });
}
function galleryPreview(node){if(!galleryItems.length){paragraph(node,'No images selected.');return}for(const [index,item]of galleryItems.entries()){paragraph(node,'Image '+(index+1)+' of '+galleryItems.length+(item.pending?' · Uploading…':''));imageFigure(node,item);if(item.caption)paragraph(node,item.caption);if(item.outbound){const destination=action(node,item.outbound,()=>{let notice=node.querySelector('.link-result');if(!notice){notice=paragraph(node,'');notice.className='link-result';notice.setAttribute('role','status')}notice.textContent='Link destination: '+item.outbound});destination.className='preview-url';destination.setAttribute('aria-label','Preview image '+(index+1)+' link destination')}}}
function pauseComposerVideos(){for(const video of document.querySelectorAll('video')){video.relaxeStartRequested=false;video.pause()}}
function videoSampleUrl(){if(videoBlobUrl)return Promise.resolve(videoBlobUrl);if(!videoBlobPromise)videoBlobPromise=fetch('assets/garden.mp4').then(response=>{if(!response.ok)throw new Error('Sample unavailable');return response.blob()}).then(blob=>{if(videoPageLeaving)throw new Error('Page left');videoBlobUrl=URL.createObjectURL(blob);return videoBlobUrl}).catch(error=>{videoBlobPromise=null;throw error});return videoBlobPromise}
function timeLabel(seconds){const total=Math.max(0,Math.floor(Number.isFinite(seconds)?seconds:0));return Math.floor(total/60)+':'+String(total%60).padStart(2,'0')}
function buildVideoPlayer(node,id,choice,position=0){
 const frame=document.createElement('figure');frame.className='video-frame';
 const player=document.createElement('video');player.id=id;player.preload='metadata';player.playsInline=true;player.muted=true;player.loop=true;player.setAttribute('aria-label',choice.name);frame.append(player);
 const caption=document.createElement('figcaption');caption.textContent=choice.name+(choice.source==='camera'?' · Camera':'');frame.append(caption);
 const context=id==='video-player'?'selected video':id==='record-preview'?'recording preview':'post preview video',controls=document.createElement('div');controls.className='video-playback';
 const play=action(controls,'Play',()=>{if(player.paused)startVideo(player);else player.pause()});
 const back=action(controls,'−10s',()=>{player.currentTime=Math.max(0,player.currentTime-10)});back.setAttribute('aria-label','Back 10 seconds in '+context);
 const forward=action(controls,'+10s',()=>{if(Number.isFinite(player.duration))player.currentTime=Math.min(player.duration,player.currentTime+10)});forward.setAttribute('aria-label','Forward 10 seconds in '+context);
 const mute=action(controls,'Unmute',()=>{player.muted=!player.muted});frame.append(controls);
 const seekLabel=document.createElement('label');seekLabel.className='video-seek';seekLabel.textContent='Position';const seek=document.createElement('input');seek.type='range';seek.min='0';seek.max='0';seek.step='.1';seek.value='0';seek.setAttribute('aria-label','Position in '+context);seekLabel.append(seek);frame.append(seekLabel);seek.addEventListener('input',()=>{player.currentTime=+seek.value});
 const clock=document.createElement('output');clock.setAttribute('aria-live','off');frame.append(clock);const notice=paragraph(frame,'');notice.className='field-help';notice.hidden=true;player.relaxeNotice=notice;
 const update=()=>{const locked=id==='video-player'&&(posting||closed),duration=Number.isFinite(player.duration)?player.duration:0;play.textContent=player.paused?'Play':'Pause';play.setAttribute('aria-label',(player.paused?'Play ':'Pause ')+context);mute.textContent=player.muted?'Unmute':'Mute';mute.setAttribute('aria-label',(player.muted?'Unmute ':'Mute ')+context);for(const button of [play,back,forward,mute])button.disabled=locked;back.disabled=locked||!duration;forward.disabled=locked||!duration;seek.disabled=locked||!duration;seek.max=String(duration);seek.value=String(player.currentTime||0);seek.setAttribute('aria-valuetext',timeLabel(player.currentTime)+' of '+timeLabel(duration));clock.textContent=timeLabel(player.currentTime)+' / '+timeLabel(duration)};
 for(const event of ['play','pause','timeupdate','durationchange','volumechange','ended'])player.addEventListener(event,update);
 player.addEventListener('loadedmetadata',()=>{if(position&&Number.isFinite(player.duration))player.currentTime=Math.min(position,player.duration);update()},{once:true});
 player.addEventListener('error',()=>{notice.hidden=false;notice.textContent='Couldn’t play this preview. Your video selection is kept.';update()});player.relaxeRefresh=update;node.append(frame);update();
 player.relaxeAttach=()=>{if(player.relaxeLoading||player.getAttribute('src'))return;player.relaxeLoading=true;videoSampleUrl().then(url=>{player.relaxeLoading=false;if(!player.isConnected)return;player.src=url;player.load();if(player.relaxeStartRequested)startVideo(player)}).catch(()=>{player.relaxeLoading=false;if(!player.isConnected)return;notice.hidden=false;notice.textContent='Couldn’t load the bundled video. Use Play to retry.'})};player.relaxeAttach();return player;
}
function startVideo(player){if(!player||!player.isConnected)return;player.relaxeStartRequested=true;player.relaxeNotice.hidden=true;if(!player.getAttribute('src')){player.relaxeAttach();return}player.play().catch(()=>{if(!player.isConnected)return;player.relaxeStartRequested=false;player.relaxeNotice.hidden=false;player.relaxeNotice.textContent='Playback did not start. Use Play to try again.';player.relaxeRefresh()})}
function renderVideo(){const selected=Boolean(videoChoice);C('video-empty').hidden=selected;C('video-selected').hidden=!selected;if(!selected){C('video-slot').replaceChildren();return}const unavailable=C('compose-video-result').value==='preview-error';C('video-slot').hidden=unavailable;C('video-unavailable').hidden=!unavailable;C('video-retry').hidden=!unavailable;const player=C('video-player');if(unavailable)player?.pause();player?.relaxeRefresh();for(const button of document.querySelectorAll('#video-form>div>.image-actions button,#video-empty button'))button.disabled=posting||closed}
function acceptVideo(source){if(posting||closed)return;pauseComposerVideos();videoChoice={src:'assets/garden.mp4',name:source==='camera'?'recorded-video.mp4':'garden.mp4',source};C('video-slot').replaceChildren();const player=buildVideoPlayer(C('video-slot'),'video-player',videoChoice);message('video-error','');message('post-error','');message('post-result','');sync();dialogOrigin=C('video-replace');dialog.close();if(C('compose-video-result').value!=='preview-error')startVideo(player)}
function chooseVideo(){if(posting||closed)return;if(C('compose-video-result').value==='picker-error'){message('video-error','Couldn’t select a video. Try again.');if(dialog.open)dialog.close();return}show('Choose video',node=>{action(node,'Choose garden.mp4',()=>acceptVideo('library'));action(node,'Cancel',()=>dialog.close())})}
function recordVideo(){if(posting||closed)return;const result=C('compose-video-result').value;if(result==='camera-denied'||result==='camera-unavailable'){message('video-error',result==='camera-denied'?'Camera access is required to record a video. You can choose a video instead.':'No camera is available. You can choose a video instead.');if(dialog.open)dialog.close();return}show('Recording preview',node=>{buildVideoPlayer(node,'record-preview',{src:'assets/garden.mp4',name:'Sample recording',source:'camera'});const actions=document.createElement('div');actions.className='dialog-actions';action(actions,'Cancel',()=>dialog.close());action(actions,'Use recording',()=>acceptVideo('camera'),true);node.append(actions)})}
function replaceVideo(){if(posting||closed)return;show('Replace video',node=>{const actions=document.createElement('div');actions.className='image-actions';action(actions,'Choose video',chooseVideo);action(actions,'Record video',recordVideo);node.append(actions);action(node,'Cancel',()=>dialog.close())})}
function inline(node,text){const tokens=/\*\*([^*]+)\*\*|\*([^*]+)\*|`([^`]+)`|\[([^\]]+)\]\(([^)]+)\)/g;let last=0,match;while((match=tokens.exec(text))){node.append(document.createTextNode(text.slice(last,match.index)));const tag=document.createElement(match[1]?'strong':match[2]?'em':match[3]?'code':'a');tag.textContent=match[1]||match[2]||match[3]||match[4];if(match[4]){tag.href='#';tag.addEventListener('click',event=>{event.preventDefault();let notice=content.querySelector('.link-result');if(!notice){notice=paragraph(content,'');notice.className='link-result';notice.setAttribute('role','status')}notice.textContent='Link destination: '+matchUrl(tag);});tag.dataset.url=match[5]}node.append(tag);last=tokens.lastIndex}node.append(document.createTextNode(text.slice(last)))}
function matchUrl(tag){return tag.dataset.url}
function preview(){show('Post preview',node=>{node.className='dialog-preview';paragraph(node,(guest()?'Guest':'u/'+C('post-account').value)+' · '+(C('post-subreddit').value?'r/'+C('post-subreddit').value:'No subreddit selected'));const title=document.createElement('h4');title.textContent=C('post-title').value||'Untitled post';node.append(title);if(activeType==='video'){if(videoChoice&&C('compose-video-result').value!=='preview-error')buildVideoPlayer(node,'post-video-preview',videoChoice,C('video-player')?.currentTime||0);else paragraph(node,videoChoice?'Video preview unavailable. Your selection is kept.':'No video selected.')}if(activeType==='gallery')galleryPreview(node);if(activeType==='image'){if(imageChoice)imageFigure(node);else paragraph(node,'No image selected.')}if(activeType==='link'){const url=C('post-url').value;if(url){const destination=action(node,url,()=>{let notice=node.querySelector('.link-result');if(!notice){notice=paragraph(node,'');notice.className='link-result';notice.setAttribute('role','status')}notice.textContent='Link destination: '+url});destination.className='preview-url';destination.setAttribute('aria-label','Preview link destination')}else paragraph(node,'No URL entered.')}for(const line of C('post-body').value.split('\n')){if(!line){node.append(document.createElement('br'));continue}const quote=line.startsWith('> '),list=/^[-*] /.test(line),block=document.createElement(quote?'blockquote':list?'ul':'p');if(list){const item=document.createElement('li');inline(item,line.slice(2));block.append(item)}else inline(block,quote?line.slice(2):line);node.append(block)}if(!C('post-body').value)paragraph(node,'No body text.');if(activeType==='poll')pollPreview(node);paragraph(node,'Preview only. Nothing has been posted.');})}
function cancelSuggestion(){clearTimeout(suggestionTimer);suggestionGeneration++;suggesting=false;C('suggest-title').disabled=posting||closed;C('suggest-title').textContent='Suggest title';message('suggestion-status','')}
function suggestTitle(){if(suggesting||posting||closed||activeType!=='link')return;cancelSuggestion();if(!C('post-url').value.trim()){message('url-error','Add a URL before suggesting a title.');C('post-url').setAttribute('aria-invalid','true');C('post-url').focus();return}const generation=suggestionGeneration,fail=C('compose-title-result').value==='failure';suggesting=true;message('suggestion-status','Getting title…');sync();suggestionTimer=setTimeout(()=>{if(generation!==suggestionGeneration)return;suggesting=false;if(fail)message('suggestion-status','Couldn’t suggest a title. Your title is kept. Try again or write your own.');else{C('post-title').value='A practical guide to growing basil indoors';message('title-error','');C('post-title').removeAttribute('aria-invalid');message('suggestion-status','Title added. You can edit it.')}sync()},650)}
function format(kind){const field=C('post-body'),selected=field.value.slice(field.selectionStart,field.selectionEnd)||'text',pairs={bold:['**','**'],italic:['*','*'],link:['[','](https://example.com)'],code:['`','`'],quote:['> ',''],list:['- ',''],strike:['~~','~~'],spoiler:['>!','!<']},pair=pairs[kind];if(!pair)return;if(dialog.open){dialogOrigin=field;dialog.close()}field.setRangeText(pair[0]+selected+pair[1],field.selectionStart,field.selectionEnd,'select');field.focus();field.dispatchEvent(new Event('input',{bubbles:true}))}
function leave(next){pauseComposerVideos();cancelSuggestion();if(!dirty()&&!posting){next();return}leaveAction=next;show(posting?'Leave while posting?':'Discard this post?',node=>{paragraph(node,posting?'Posting is in progress. In the app, leaving may not stop submission. This study sends nothing.':'Your entered title, URL, bodies, poll options and selected media will be discarded.');const actions=document.createElement('div');actions.className='dialog-actions';action(actions,'Keep composing',()=>dialog.close());action(actions,posting?'Leave composer':'Discard',()=>{if(!posting){for(const id of ['post-title','post-body','post-url'])C(id).value='';for(const type of Object.keys(bodies))bodies[type]='';imageChoice=null;videoChoice=null;galleryItems=[];pollOptions=[{id:++pollSequence,value:''},{id:++pollSequence,value:''}];pollDuration='3';clearPollError();for(const id of ['title-error','url-error','image-error','video-error','gallery-error','gallery-status','post-error','post-result'])message(id,'');C('post-title').removeAttribute('aria-invalid');C('post-url').removeAttribute('aria-invalid')}dialog.close();const run=leaveAction;leaveAction=null;run?.()},true);node.append(actions)})}
function closeComposer(){leave(()=>{closed=true;sync();C('composer-reopen').focus()})}
for(const [id,key]of [['compose-appearance','appearance'],['compose-palette','palette'],['compose-scale','text'],['compose-width','width']])C(id).addEventListener('change',event=>{config[key]=event.target.value;theme()});
C('compose-fixture').addEventListener('change',event=>{fixture=event.target.value;if(fixture==='guest'){if(C('post-account').value!=='guest')lastSignedInAccount=C('post-account').value;C('post-account').value='guest'}else if(C('post-account').value==='guest')C('post-account').value=lastSignedInAccount;message('post-error','');message('post-result','');sync()});
for(const id of ['post-account','post-subreddit','post-type','post-flair','post-spoiler','post-nsfw','post-notifications'])C(id).addEventListener('change',()=>{if(id==='post-account'){if(C(id).value==='guest')fixture='guest';else{lastSignedInAccount=C(id).value;if(fixture==='guest')fixture='ready'}C('compose-fixture').value=fixture}message('post-result','');sync()});
for(const id of ['post-title','post-body','post-url'])C(id).addEventListener('input',()=>{if(id==='post-title'||id==='post-url')cancelSuggestion();if(id==='post-body'&&activeType in bodies)bodies[activeType]=C(id).value;message('title-error','');message('url-error','');C('post-title').removeAttribute('aria-invalid');C('post-url').removeAttribute('aria-invalid');message('post-error','');message('post-result','')});
C('suggest-title').addEventListener('click',suggestTitle);
C('compose-attachment-result').addEventListener('change',()=>{message('image-error','');sync()});
C('image-choose').addEventListener('click',chooseImage);C('image-camera').addEventListener('click',takePhoto);C('image-replace').addEventListener('click',replaceImage);
C('image-remove').addEventListener('click',()=>{if(posting||closed)return;imageChoice=null;message('image-error','');message('post-error','');message('post-result','');sync();C('image-choose').focus()});
C('image-retry').addEventListener('click',()=>{C('compose-attachment-result').value='ready';sync()});
C('gallery-add').addEventListener('click',addGallery);
C('gallery-complete').addEventListener('click',()=>{for(const item of galleryItems)item.pending=false;message('gallery-error','');message('gallery-status','Images ready.');sync();(activeType==='gallery'?C('gallery-count'):C('compose-gallery-upload')).focus()});
C('video-choose').addEventListener('click',chooseVideo);C('video-record').addEventListener('click',recordVideo);C('video-replace').addEventListener('click',replaceVideo);
C('video-remove').addEventListener('click',()=>{if(posting||closed)return;pauseComposerVideos();videoChoice=null;message('video-error','');message('post-error','');message('post-result','');sync();C('video-choose').focus()});
C('video-retry').addEventListener('click',()=>{C('compose-video-result').value='ready';sync()});
C('compose-video-result').addEventListener('change',()=>{message('video-error','');sync()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseComposerVideos()});window.addEventListener('pagehide',event=>{pauseComposerVideos();if(!event.persisted){videoPageLeaving=true;if(videoBlobUrl)URL.revokeObjectURL(videoBlobUrl)}});
C('return-text').addEventListener('click',()=>{C('post-type').value='text';sync();C('post-body').focus()});
C('post-rules').addEventListener('click',()=>show('r/'+C('post-subreddit').value+' rules',node=>{paragraph(node,'Sample rules for this design study:');const list=document.createElement('ol');for(const text of ['Keep the post relevant to the subreddit.','Use a clear title and follow its posting requirements.','Be considerate when replying.']){const item=document.createElement('li');item.textContent=text;list.append(item)}node.append(list);paragraph(node,'Native rules and allowed post types must come from the selected subreddit and account.')}));
C('retry-flair').addEventListener('click',()=>{fixture='ready';C('compose-fixture').value=fixture;sync()});
for(const button of document.querySelectorAll('[data-format]'))button.addEventListener('click',()=>format(button.dataset.format));
C('format-more').addEventListener('click',()=>show('Formatting',node=>{const group=document.createElement('div');group.className='format-options';for(const [key,label]of [['code','Code'],['quote','Quote'],['list','List'],['strike','Strikethrough'],['spoiler','Spoiler']])action(group,label,()=>format(key));if(activeType==='text'||activeType==='poll')action(group,'Insert image',()=>{content.replaceChildren();paragraph(content,'Image selection and upload will be reviewed with attachments. No file is selected or uploaded in this specimen.');C('compose-dialog-title').textContent='Insert image'});node.append(group)}));
C('poll-add').addEventListener('click',()=>{if(posting||closed||pollOptions.length>=6)return;const option={id:++pollSequence,value:''};pollOptions.push(option);clearPollError();message('post-result','');renderPoll();C('poll-option-'+option.id).focus()});
C('poll-duration').addEventListener('change',()=>{pollDuration=C('poll-duration').value;message('post-result','')});
C('post-preview').addEventListener('click',preview);C('compose-close').addEventListener('click',closeComposer);C('composer-reopen').addEventListener('click',()=>{closed=false;sync();C('post-title').focus()});
C('post-form').addEventListener('submit',event=>{event.preventDefault();if(C('compose-post').disabled)return;message('post-error','');if(!C('post-subreddit').value){message('post-error','Choose a subreddit before posting.');C('post-subreddit').focus();return}if(!C('post-title').value.trim()){message('title-error','Add a title before posting.');C('post-title').setAttribute('aria-invalid','true');C('post-title').focus();return}if(activeType==='link'&&!C('post-url').value.trim()){message('url-error','Add a URL before posting.');C('post-url').setAttribute('aria-invalid','true');C('post-url').focus();return}if(activeType==='image'&&!imageChoice){message('image-error','Choose an image before posting.');C('image-choose').focus();return}if(activeType==='gallery'&&(!galleryItems.length||galleryPending())){message('gallery-error',galleryPending()?'Wait for every image to finish uploading before posting.':'Add an image before posting.');(galleryPending()?C('gallery-count'):C('gallery-add')).focus();return}if(activeType==='video'&&!videoChoice){message('video-error','Choose a video before posting.');C('video-choose').focus();return}if(activeType==='poll'&&pollOptions.filter(option=>option.value!=='').length<2){message('poll-error','Add at least two poll options before posting.');const input=C('poll-option-'+pollOptions.find(option=>option.value==='').id);input.setAttribute('aria-invalid','true');input.focus();return}cancelSuggestion();const failAttempt=fixture==='submit-error',videoFailure=activeType==='video'?C('compose-video-result').value:'';pauseComposerVideos();posting=true;message('post-result','');sync();submitTimer=setTimeout(()=>{posting=false;if(videoFailure==='file-error')message('post-error','Couldn’t access the video file. Your writing and selection are kept. Choose it again or try another video.');else if(videoFailure==='processing-error')message('post-error','Couldn’t process the video. Your writing and selection are kept.');else if(failAttempt)message('post-error','Couldn’t post. Your writing is kept. Try again.');else message('post-result','Preview complete. No post was sent to Reddit.');sync()},650)});
C('compose-dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{for(const player of dialog.querySelectorAll('video')){player.relaxeStartRequested=false;player.pause()}content.className='';if(dialogOrigin?.isConnected&&!dialogOrigin.disabled)dialogOrigin.focus({preventScroll:true})});
dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const items=[...dialog.querySelectorAll('button,a,input,select,textarea')].filter(el=>!el.disabled&&!el.hidden),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!dialog.open&&!closed){event.preventDefault();closeComposer()}});
document.addEventListener('click',event=>{const button=event.target.closest('.shared-shell-nav [data-destination]');if(!button||button.dataset.destination==='search')return;if(allowNavigation){allowNavigation=false;return}if(!dirty()&&!posting)return;event.preventDefault();event.stopImmediatePropagation();leave(()=>{allowNavigation=true;button.click()})},true);
C('compose-close').innerHTML=T.icon('close');C('compose-dialog-close').innerHTML=T.icon('close');C('format-more').innerHTML=T.icon('more');const entryType=new URLSearchParams(location.search).get('type');if(Object.hasOwn(bodies,entryType))C('post-type').value=entryType;sync();
document.addEventListener('relaxe-shell-ready',theme,{once:true});
})();
